import idle.core.*;import idle.core.sky.*;import idle.core.upgrades.*;import idle.core.darkmatter.*;import idle.core.achievements.*;import idle.core.save.*;import java.util.*;import java.nio.file.*;
public class InspectBodies{public static void main(String[]a)throws Exception{Game g=new Game(SaveCodec.read(Files.readString(Path.of(a[0]))).state(),Upgrades.DEFAULT,Automations.DEFAULT,DarkUpgrades.DEFAULT,Achievements.DEFAULT,new Random(5));System.out.printf("bb=%d bodies=%d mature=%d needs=%d space=%s cEnergy=%.2e produced=%.2e rate=%.2e\n",g.bigBangs(),g.bodiesFormed(),g.bodiesMature(),g.bigBangSkyRequirement(),g.state().space(),g.colliderEnergy(),g.colliderEnergyProduced(),g.colliderEnergyPerSecond());for(Body b:g.bodies()){if(!g.hasBody(b.id()))System.out.printf("MISSING id=%s tier=%s cond=%d/%d can=%s from=%s assembly=%s\n",b.id(),b.tier(),g.bodyConditionsMet(b.id()),g.bodyConditions(b.id()),g.canFormBody(b.id()),b.bodies(),b.assemblies());}System.out.println("systems="+g.solarSystemsComplete()+" probe="+g.state().probeRuns());}}
